  for(const auto& item:cases){auto raw=body(false,true);raw["max_output_tokens"]=16;auto task=exchange(false,raw,streamed(item.delta,item.finish));const auto value=co_await std::move(task);const auto events=h::parseResponsesSseEvents(value.text);EXPECT_EQ(rt::getString(events.back(),"type"),item.terminal);EXPECT_EQ(value.telemetry->failureKind,item.failure.empty()?std::nullopt:std::optional(item.failure));EXPECT_EQ(value.telemetry->completed,item.terminal=="response.completed");if(item.finish=="length"){const auto* response=rt::get(events.back(),"response");EXPECT_EQ(rt::getString(*rt::get(*response,"incomplete_details"),"reason"),"max_output_tokens");EXPECT_EQ(value.telemetry->outputTokenAllowance,std::optional<double>(16));}}co_await h::settleHarness();
